    19→public class JsonParser {
    20→  private final Collection<SourceLocator> sourceRoots;
    21→
    22→  public JsonParser(final Collection<SourceLocator> sourceRoots) {
    23→    this.sourceRoots = sourceRoots;
    24→  }
    25→
    26→  private final Gson gson = new GsonBuilder().disableHtmlEscaping().create();
    27→
    28→  private final MutationIdCounter mutationIdCounter = new MutationIdCounter();
    29→
    30→  public String toJson(final PackageSummaryMap packageSummaryMap)
    31→      throws IOException {
    32→    mutationIdCounter.reset();
    33→    final Map<String, JsonFile> collectedJsonFiles = new HashMap<>();
    34→
    35→    List<PackageSummaryData> sortedPackageData = packageSummaryMap.valuesList();
    36→    Collections.sort(sortedPackageData);
    37→
    38→    for (PackageSummaryData packageData : sortedPackageData) {
    39→      for (MutationTestSummaryData testData : packageData.getSummaryData()) {
    40→        this.addToJsonFiles(collectedJsonFiles, testData);
    41→      }
    42→    }
    43→    final JsonReport report = new JsonReport(collectedJsonFiles);
    44→    return gson.toJson(report, JsonReport.class);
    45→  }
    46→
    47→  private void addToJsonFiles(final Map<String, JsonFile> collectedJsonFiles,
    48→      final MutationTestSummaryData data) throws IOException {
    49→    // Step 1: Map mutations to lines
    50→    final List<Line> lines = this.getLines(data);
    51→
    52→    // Step 2: Create or retrieve JsonFile
    53→    final String fullPath = data.getPackageName() + "/" + data.getFileName();
    54→    if (collectedJsonFiles.get(fullPath) == null) {
    55→      collectedJsonFiles.put(fullPath, new JsonFile());
    56→    }
    57→    final JsonFile file = collectedJsonFiles.get(fullPath);
    58→
    59→    // Step 3: Add source and mutants to file
    60→    file.addSource(this.getSourceFromLines(lines));
    61→    file.addMutants(this.getMutantsFromLines(lines, data));
    62→  }
    63→
    64→  private List<JsonMutant> getMutantsFromLines(final List<Line> lines,
    65→      final MutationTestSummaryData data) {
    66→    final List<JsonMutant> jsonMutants = new ArrayList<>();
    67→    if (lines.isEmpty()) {
    68→      // If there are no lines, add the mutants anyway, without source
    69→      for (MutationResult mutationResult : data.getResults()) {
    70→        jsonMutants
    71→            .add(this.mapToJsonMutant(mutationResult, JsonLocation.empty()));
    72→      }
    73→    } else {
    74→      for (final Line line : lines) {
    75→        for (MutationResult mutationResult : line.getMutations()) {
    76→          jsonMutants.add(
    77→              this.mapToJsonMutant(mutationResult, JsonLocation.ofLine(line)));
    78→        }
    79→      }
    80→    }
    81→    return jsonMutants;
    82→  }
