    72→      }
    73→    } else {
    74→      for (final Line line : lines) {
    75→        for (MutationResult mutationResult : line.getMutations()) {
    76→          jsonMutants.add(
    77→              this.mapToJsonMutant(mutationResult, JsonLocation.ofLine(line)));
    78→        }
    79→      }
    80→    }
    81→    return jsonMutants;
    82→  }
    83→
    84→  private String getSourceFromLines(final List<Line> lines) {
    85→    if (lines.isEmpty()) {
    86→      return "   ";
    87→    }
    88→    StringBuilder builder = new StringBuilder();
    89→    for (final Line line : lines) {
    90→      builder.append(line.getText());
    91→      builder.append("\n");
    92→    }
    93→    return builder.toString();
    94→  }
    95→
    96→  private List<Line> getLines(final MutationTestSummaryData summaryData)
    97→      throws IOException {
    98→    final String fileName = summaryData.getFileName();
    99→    final Collection<ClassInfo> classes = summaryData.getClasses();
   100→    final Optional<Reader> reader = findReaderForSource(classes, fileName);
   101→    if (reader.isPresent()) {
   102→      final LineFactory lineFactory = new LineFactory(summaryData.getResults());
   103→      return lineFactory.convert(reader.get());
   104→    }
   105→    return Collections.emptyList();
   106→  }
   107→
   108→  private Optional<Reader> findReaderForSource(
   109→      final Collection<ClassInfo> classes, final String fileName) {
   110→    for (final SourceLocator each : this.sourceRoots) {
   111→      final Optional<Reader> maybe = each
   112→          .locate(this.classInfoToNames(classes), fileName);
   113→      if (maybe.isPresent())
   114→        return maybe;
   115→    }
   116→    return Optional.empty();
   117→  }
   118→
   119→  private Collection<String> classInfoToNames(
   120→      final Collection<ClassInfo> classes) {
   121→    return FCollection.map(classes, a -> a.getName().asJavaName());
   122→  }
   123→
   124→  private JsonMutant mapToJsonMutant(final MutationResult mutation,
   125→      final JsonLocation location) {
   126→    final String fullMutatorName = mutation.getDetails().getMutator();
   127→    // Only show the class name
   128→    final String mutatorName = fullMutatorName
   129→        .substring(fullMutatorName.lastIndexOf(".") + 1);
   130→
   131→    final JsonMutantStatus status = JsonMutantStatus
   132→        .fromPitestStatus(mutation.getStatus());
   133→    return new JsonMutant(Integer.toString(mutationIdCounter.next()), mutatorName,
   134→        mutation.getDetails().getDescription(), location, status);
   135→  }
